import torch

def _failure(code, path, message, retryable=False):
    return {'success': False, 'error': {'code': code, 'path': path, 'message': message, 'retryable': retryable}}


def _scope_path(context, relative_path, must_exist=True):
    from pathlib import Path
    root = context.scope_root('opc_workspace').resolve()
    candidate = (root / relative_path).resolve()
    try:
        candidate.relative_to(root)
    except ValueError as error:
        raise ValueError('Path escapes opc_workspace.') from error
    if must_exist and not candidate.is_file():
        raise FileNotFoundError(relative_path)
    return candidate



def _parse_config(text):
    values = {}
    for raw in text.splitlines():
        pieces = raw.strip().split()
        if len(pieces) >= 2:
            values[pieces[0]] = pieces[1]
    required = ('KernelNum', 'DoseNom', 'DoseMin')
    if any(key not in values for key in required):
        raise ValueError('Model configuration lacks KernelNum, DoseNom, or DoseMin.')
    return {'KernelNum': int(values['KernelNum']), 'DoseNom': float(values['DoseNom']), 'DoseMin': float(values['DoseMin'])}


def _kernel_mult(kernels, mask_fft, count):
    kh, kw = kernels.shape[-2:]
    hh, hw = kh // 2, kw // 2
    output = torch.zeros((count, mask_fft.shape[-2], mask_fft.shape[-1]), dtype=mask_fft.dtype)
    output[:, :hh + 1, :hw + 1] = mask_fft[:, :hh + 1, :hw + 1] * kernels[:count, -(hh + 1):, -(hw + 1):]
    output[:, :hh + 1, -hw:] = mask_fft[:, :hh + 1, -hw:] * kernels[:count, -(hh + 1):, :hw]
    output[:, -hh:, :hw + 1] = mask_fft[:, -hh:, :hw + 1] * kernels[:count, :hh, -(hw + 1):]
    output[:, -hh:, -hw:] = mask_fft[:, -hh:, -hw:] * kernels[:count, :hh, :hw]
    return output


def run(arguments, context):
    mask_id, model_id = arguments['mask_raster_id'], arguments['model_config_id']
    mask_record = context.records.get('raster_masks', {'raster_id': mask_id})
    if mask_record is None:
        return _failure('not_found', 'mask_raster_id', 'No raster mask exists for the supplied ID.')
    model = context.records.get('optical_configs', {'config_id': model_id})
    if model is None:
        return _failure('not_found', 'model_config_id', 'No model configuration exists for the supplied ID.')
    if model['config_kind'] != 'text_parameters':
        return _failure('invalid_config', 'model_config_id', 'The model configuration must be a text parameter record.')
    kernel_records = []
    for index, config_id in enumerate(arguments['kernel_config_ids']):
        record = context.records.get('optical_configs', {'config_id': config_id})
        if record is None:
            return _failure('not_found', 'kernel_config_ids[' + str(index) + ']', 'No kernel configuration exists for the supplied ID.')
        kernel_records.append(record)
    condition = arguments['focus_condition']
    expected_word = 'defocus' if condition == 'defocus' else 'focus'
    if any(record['config_kind'] != 'torch_tensor_archive' for record in kernel_records) or any(expected_word not in record['config_id'].lower() for record in kernel_records):
        return _failure('incompatible_model', 'kernel_config_ids', 'Kernel records do not match the requested focus condition.')
    if any(record['experiment_id'] != model['experiment_id'] for record in kernel_records):
        return _failure('incompatible_model', 'kernel_config_ids', 'Model and kernels are not from the shared optical model.')
    try:
        mask_path = _scope_path(context, mask_record['source_path'])
        model_path = _scope_path(context, model['source_path'])
        kernel_paths = [_scope_path(context, record['source_path']) for record in kernel_records]
    except ValueError as error:
        return _failure('invalid_path', 'kernel_config_ids', str(error))
    except FileNotFoundError:
        return _failure('missing_file', 'kernel_config_ids', 'A registered model input file is missing.')
    try:
        config = _parse_config(model_path.read_text(encoding='utf-8'))
        loaded = [torch.load(path, map_location='cpu', weights_only=True) for path in kernel_paths]
        complex_items = [item for item in loaded if isinstance(item, torch.Tensor) and item.is_complex() and item.ndim == 3]
        real_items = [item for item in loaded if isinstance(item, torch.Tensor) and not item.is_complex() and item.ndim == 1]
        if len(complex_items) != 1 or len(real_items) != 1:
            return _failure('invalid_kernel', 'kernel_config_ids', 'Exactly one 3-D complex kernel and one 1-D real scale tensor are required.')
        kernels = complex_items[0].permute(2, 0, 1).to(torch.complex64)
        scales = real_items[0].to(torch.float32)
        count = config['KernelNum']
        if count < 1 or count > kernels.shape[0] or count > scales.shape[0]:
            return _failure('invalid_kernel', 'kernel_config_ids', 'KernelNum exceeds the supplied kernel or scale tensor.')
        with Image.open(mask_path) as image:
            pixels = np.asarray(image.convert('L'), dtype=np.float32)
        if pixels.shape[0] < kernels.shape[1] or pixels.shape[1] < kernels.shape[2]:
            return _failure('incompatible_model', 'mask_raster_id', 'Mask dimensions are smaller than the optical kernel.')
        mask = torch.from_numpy(pixels / (255.0 if float(pixels.max()) > 1.0 else 1.0))
        dose = config['DoseMin'] if condition == 'defocus' else config['DoseNom']
        cmask = (mask * dose).to(torch.complex64).unsqueeze(0)
        mask_fft = torch.fft.fft2(cmask, norm='forward')
        filtered = _kernel_mult(kernels, mask_fft, count)
        fields = torch.fft.ifft2(filtered, norm='forward')
        aerial = torch.sum(scales[:count, None, None] * torch.abs(fields) ** 2, dim=0).real
        if not bool(torch.isfinite(aerial).all()):
            return _failure('processing_failed', 'kernel_config_ids', 'The OpenILT convolution produced non-finite values.')
        values = aerial.detach().cpu().numpy()
        return {'success': True, 'data': {
            'mask_raster_id': mask_id, 'model_config_id': model_id, 'kernel_config_ids': arguments['kernel_config_ids'],
            'focus_condition': condition, 'dose': float(dose), 'kernel_count': count, 'shape': list(values.shape),
            'aerial_image': values.tolist(), 'intensity_min': float(values.min()), 'intensity_max': float(values.max()),
            'intensity_mean': float(values.mean()), 'intensity_sum': float(values.sum()),
        }}
    except (OSError, RuntimeError, ValueError, TypeError) as error:
        return _failure('processing_failed', 'kernel_config_ids', 'OpenILT simulation failed: ' + str(error), True)

